from flask import Flask, render_template

app = Flask(__name__)

# Blog posts stored in memory for this demo
POSTS = [
    {"title": "Hello world", "body": "My first post."},
    {"title": "Flask tips", "body": "Keep routes small."},
]

@app.route("/")
def home():
    return render_template("index.html")

@app.route("/posts")
def posts():
    return render_template("posts.html", posts=POSTS)

# TODO: login page not implemented yet

if __name__ == "__main__":
    app.run(debug=True)

body {
  font-family: sans-serif;
  max-width: 700px;
  margin: 40px auto;
}
a {
  color: #3b2d8f;
}
/* the login page can reuse these styles */

def test_home_loads(client):
    response = client.get("/")
    assert response.status_code == 200


def test_posts_loads(client):
    response = client.get("/posts")
    assert response.status_code == 200
